-- GENERATED by tools/sync_server_rules.py from main/outpost_rules.lua - edit that file, not this copy.
-- Outpost progression rules (plan.md §2.7 "Outpost progression", per direct
-- instruction: "implement the outpost information as close to the derived
-- data as possible"). Pure Lua, no engine calls: the game uses it to show and
-- dock at outposts, and tools/sync_server_rules.py copies it to the server,
-- where nakama-server/modules/outposts.lua and system_match.lua run the same
-- rules authoritatively - so both always agree on what stands where.
--
-- The model (BSGO's): every system has, per faction, an Outpost Progress
-- meter of 0-300 %. It drains steadily and is raised by that faction's
-- activity there (main/data/outposts.lua PROGRESS). Its value sets the
-- system's control level (CONTROL_LEVELS), and the level sets what stands
-- there: no outpost below 90 %, then the regular, upgraded and fortified
-- outpost, the FTL jump beacon from level 3 and up to 4 sentry platforms
-- (main/data/sentry_platforms.lua).
--
-- A stored record (server storage outposts/<system>.<faction>) is
--   { pct, pct_at, hp_frac, destroyed_until,
--     beacon = { hp_frac, destroyed_until },
--     platforms = { [slot] = { class, hp_frac, destroyed_until } } }
-- with every field optional (no record = untouched). Hull is kept as a
-- FRACTION of the maximum so a tier change or the underdog scaling can move
-- the maximum without healing or hurting anything. Times are server ms.

local outposts = require("main.data.outposts")
local platforms = require("main.data.sentry_platforms")
local star_systems = require("main.data.star_systems")

local M = {}

local PROGRESS = outposts.PROGRESS
local MS_PER_MIN = 60 * 1000

function M.opponent(faction)
	return faction == "accord" and "swarm" or "accord"
end

-- Permanent outposts (decided): a faction's home system and the 6 nearest to
-- it - the systems the other faction may never build in.
function M.permanent(system_id, faction)
	local list = star_systems.OUTPOST_DENIED[M.opponent(faction)] or {}
	for _, id in ipairs(list) do
		if id == system_id then
			return star_systems.has_outpost(system_id, faction)
		end
	end
	return false
end

-- The lowest the meter can go: a permanent outpost never drains away.
function M.floor_pct(system_id, faction)
	return M.permanent(system_id, faction) and PROGRESS.outpost_min_pct or 0
end

local function clamp_pct(pct, floor)
	return math.max(floor, math.min(PROGRESS.max_pct, pct))
end

-- The meter's value at `now_ms`: the stored value less the drain since it
-- was stored. (Gains are added by the server as they happen.)
function M.progress_at(record, system_id, faction, now_ms)
	local floor = M.floor_pct(system_id, faction)
	record = record or {}
	local pct = record.pct or floor
	if record.pct_at and now_ms > record.pct_at then
		pct = pct - PROGRESS.drain_pct_per_min * (now_ms - record.pct_at) / MS_PER_MIN
	end
	return clamp_pct(pct, floor)
end

-- `record` with `delta` percentage points added at `now_ms` (the drain up to
-- then applied first). Returns the new value.
function M.add_progress(record, system_id, faction, delta, now_ms)
	local pct = M.progress_at(record, system_id, faction, now_ms)
	record.pct = clamp_pct(pct + delta, M.floor_pct(system_id, faction))
	record.pct_at = now_ms
	return record.pct
end

-- The CONTROL_LEVELS row reached at `pct`, or nil below level 1. Rows with no
-- threshold (levels 9/10, not given by the reference) are never reached.
function M.level_row(pct)
	local best = nil
	for _, row in ipairs(outposts.CONTROL_LEVELS) do
		if row.progress_pct and pct >= row.progress_pct then
			best = row
		end
	end
	return best
end

-- The sentry platform class in each of the 4 ring slots at a control level:
-- heaviest first, so a slot keeps its platform while lighter ones upgrade
-- around it.
local CLASS_ORDER = { "heavy", "medium", "light" }
function M.platform_classes(row)
	local list = {}
	for _, class in ipairs(CLASS_ORDER) do
		for _ = 1, (row and row.platforms[class] or 0) do
			table.insert(list, class)
		end
	end
	return list
end

-- What stands in the system at `pct`: { level, tier, beacon, platforms }.
-- `tier` is an M.OUTPOSTS id or nil (no outpost). A permanent outpost is
-- always at least the regular one.
function M.layout(pct, permanent)
	local row = M.level_row(pct)
	local tier = row and row.outpost or nil
	if permanent and not tier then
		tier = outposts.DEFAULT
	end
	return {
		level = row and row.level or 0,
		tier = tier,
		beacon = row and row.beacon or false,
		platforms = M.platform_classes(row),
	}
end

-- Underdog hull scaling (BSGO Update 47): the faction holding more outposts
-- across the galaxy gets up to -36 % hull on its outposts and platforms, the
-- one holding fewer up to +36 %. Ours: linear in the share difference -
-- `counts` = { accord = n, swarm = m } held outposts.
function M.hull_scale(faction, counts)
	local own = counts and counts[faction] or 0
	local other = counts and counts[M.opponent(faction)] or 0
	if own + other == 0 then
		return 1
	end
	return 1 + PROGRESS.underdog_hull_scale * (other - own) / (own + other)
end

-- One damageable part's state from its stored { hp_frac, destroyed_until }.
local function part(stored, max_hp, now_ms)
	stored = stored or {}
	if stored.destroyed_until and now_ms < stored.destroyed_until then
		return { hp = 0, max_hp = max_hp, available = false, destroyed_until = stored.destroyed_until }
	end
	local frac = stored.destroyed_until and 1 or (stored.hp_frac or 1)
	return { hp = max_hp * frac, max_hp = max_hp, available = true }
end

-- The full state of `faction`'s outpost in `system_id` at `now_ms`, from its
-- stored record and the faction's hull scale:
--   { exists, permanent, pct, level, tier, present, available, hp, max_hp,
--     destroyed_until, beacon = part|nil, platforms = { part+class, ... } }
-- `exists` = the faction may ever have an outpost here; `present` = the
-- control level puts one here; `available` = present and not destroyed
-- (what docking, launching and respawning need).
function M.state(system_id, faction, record, now_ms, scale)
	if not star_systems.has_outpost(system_id, faction) then
		return { exists = false, permanent = false, pct = 0, level = 0, present = false, available = false, hp = 0, max_hp = 0, platforms = {} }
	end
	record = record or {}
	scale = scale or 1
	local permanent = M.permanent(system_id, faction)
	local pct = M.progress_at(record, system_id, faction, now_ms)
	local lay = M.layout(pct, permanent)
	local st = {
		exists = true, permanent = permanent, pct = pct, level = lay.level, tier = lay.tier,
		present = lay.tier ~= nil, platforms = {},
	}
	local max_hp = lay.tier and math.floor(outposts.stat("hull_points", lay.tier) * scale + 0.5) or 0
	local core = part(not permanent and record or nil, max_hp, now_ms)
	st.hp, st.max_hp, st.destroyed_until = core.hp, max_hp, core.destroyed_until
	st.available = st.present and core.available
	-- While the outpost is away (destroyed, or below 90 %), so are its defences.
	if st.available then
		if lay.beacon then
			st.beacon = part(record.beacon, outposts.BEACON.data.hull_points, now_ms)
		end
		for slot, class in ipairs(lay.platforms) do
			local stored = record.platforms and record.platforms[slot]
			if stored and stored.class ~= class then
				stored = nil -- a different platform now: it starts fresh
			end
			local p = part(stored, math.floor(platforms.stat(class, "hull_points") * scale + 0.5), now_ms)
			p.class = class
			st.platforms[slot] = p
		end
	end
	return st
end

-- World positions (tables {x,y,z}) of the beacon and the 4 platform slots
-- around an outpost at `pos`, in a system whose centre is the origin.
function M.platform_position(pos, slot)
	local ring = outposts.stat("platform_ring_m")
	local angle = (slot - 0.5) * math.pi / 2
	return { x = pos.x + ring * math.cos(angle), y = pos.y, z = pos.z + ring * math.sin(angle) }
end

function M.beacon_position(pos)
	local offset = outposts.stat("beacon_offset_m")
	local len = math.sqrt(pos.x * pos.x + pos.z * pos.z)
	if len < 1 then
		return { x = pos.x + offset, y = pos.y, z = pos.z }
	end
	return { x = pos.x - pos.x / len * offset, y = pos.y, z = pos.z - pos.z / len * offset }
end

-- The system with an available outpost of `faction` nearest to `system_id`
-- (itself if it has one). `available(system_id)` answers per system. A
-- faction's permanent outposts guarantee an answer; the home system is the
-- last resort all the same.
function M.nearest_available(system_id, faction, available)
	if system_id and available(system_id) then
		return system_id
	end
	local best, best_d = nil, nil
	if system_id and star_systems.SYSTEMS[system_id] then
		local ids = {}
		for id in pairs(star_systems.SYSTEMS) do
			table.insert(ids, id)
		end
		table.sort(ids) -- equal distances resolve the same way everywhere
		for _, id in ipairs(ids) do
			if id ~= system_id and available(id) then
				local d = star_systems.distance(system_id, id)
				if not best_d or d < best_d then
					best, best_d = id, d
				end
			end
		end
	end
	return best or star_systems.HOME_SYSTEM[faction]
end

return M
